r"""
Crescopus - social login (Google, LinkedIn, GitHub)

  - "Continue with Google / LinkedIn / GitHub" on Log in and Sign up.
  - New people choose Builder or Grower once, on a short "Finish setting up"
    page (also name, country, optional About you). No menu until they have.
  - Their Google/LinkedIn/GitHub photo is offered for their card and copied
    into Crescopus storage (LinkedIn photo links expire).
  - An existing account with the same verified email signs straight in.
  - md/SOCIAL_LOGIN_SETUP.md: step-by-step setup for Supabase and each provider.

HOW TO USE
  1. Save this file in your Crescopus project folder (next to wsgi.py).
  2. In PowerShell, in that folder, with your venv active:
         python apply_social_login.py
  3. No SQL to run, and nothing new in .env or Render.
  4. Follow md/SOCIAL_LOGIN_SETUP.md to switch on each provider in Supabase.
  5. Any file it replaces is copied first to _backup_apply_social_login\.

It checks each file matches the version on GitHub first. If you've changed
one locally since your last push, it stops without writing anything.
Your .env is never read or changed.
"""
import base64, hashlib, os, shutil, sys

# (path, new content, sha256s of the versions it may replace)
FILES = [
    ('app/__init__.py', '', ['202d8916f84005dd42dea2244e427004ab7234c16b2ebe8a42f3d11d047d5517']),
    ('app/auth/routes.py', '', ['93086f3845afda8f924e16ef497d870cc551f629590ae4ef30a498a8500501dd']),
    ('app/static/css/cresco-ui.css', '', ['352e05ef93e84cf1ff3c6a94ec653fad36ee18be18254045c4dcaf4f1c39fab9']),
    ('app/templates/auth/_social.html', '', []),
    ('app/templates/auth/finish.html', '', []),
    ('app/templates/auth/login.html', '', ['e793e247dc5b0000446d8b83926754031d521a79306ab8c308946c349bf26f61']),
    ('app/templates/auth/signup.html', '', ['def254c821a61cd62ce148fd60c84a79ffcdb490163cf23348f7ff3eb2113325']),
    ('app/templates/base.html', '', ['5181480691e7242cde23d07cc52ca5ac2781436d6d16295077bcceb5cc50918a']),
    ('md/SOCIAL_LOGIN_SETUP.md', '', []),
]
BACKUP = "_backup_apply_social_login"
NEXT = "follow md/SOCIAL_LOGIN_SETUP.md to switch on Google, LinkedIn and GitHub in Supabase, restart python wsgi.py, try each button, then commit and push."

def sha(data):
    return hashlib.sha256(data).hexdigest()

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")

    # Safety check first: never overwrite local changes we don't know about.
    clashes = []
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        new = base64.b64decode(b64)
        if not os.path.exists(path):
            if expected:
                clashes.append(rel + " (missing)")
            continue
        with open(path, "rb") as fh:
            current = fh.read()
        current_norm = current.replace(b"\r\n", b"\n")
        if current == new or current_norm == new:
            continue
        if not expected or sha(current_norm) not in expected:
            clashes.append(rel)
    if clashes:
        print("Stopped - nothing written. These files differ from the version this update was built from:")
        for c in clashes:
            print("   " + c)
        sys.exit("Push or share your latest changes and ask for the update to be rebuilt.")

    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                current = fh.read()
            if current == data or current.replace(b"\r\n", b"\n") == data:
                print("same     " + rel)
                continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
